//! Replays `packages/test-vectors/crypto/e2e-mail.json`, generated by the TypeScript side: reproducing its bytes
//! exactly (payload, signature, envelope) is what makes a mail sealed by either side open and verify in the other.

use std::cell::Cell;

use ed25519_dalek::{Signer, SigningKey};
use serde_json::Value;
use sha2::{Digest, Sha256};

use super::*;
use crate::crypto::seal_envelope_for_vectors;
use crate::crypto::test_vectors::{array, bytes, items, load, number, text};

/// A mail from the JSON with owned fields, or `None` if the Rust types cannot hold it (a 15-byte id, a negative
/// date…).
struct MailData {
    message_id: [u8; MESSAGE_ID_LENGTH],
    date: u64,
    sender: ([u8; 32], String),
    recipient: ([u8; 32], String),
    subject: String,
    body: String,
}

/// Byte `i` is `a` + `i mod 26`.
fn body_pattern(length: usize) -> String {
    (0..length).map(|i| char::from(b'a' + u8::try_from(i % 26).unwrap())).collect()
}

fn party_from(v: &Value) -> Option<([u8; 32], String)> {
    Some((hex::decode(v["addrKey"].as_str()?).ok()?.try_into().ok()?, v["address"].as_str()?.to_owned()))
}

impl MailData {
    fn from_json(v: &Value) -> Option<Self> {
        let body = match v.get("body") {
            Some(body) => body.as_str()?.to_owned(),
            None => body_pattern(number(&v["bodyLength"])),
        };
        Some(Self {
            message_id: hex::decode(v["messageId"].as_str()?).ok()?.try_into().ok()?,
            date: v["date"].as_u64()?,
            sender: party_from(&v["sender"])?,
            recipient: party_from(&v["recipient"])?,
            subject: v["subject"].as_str()?.to_owned(),
            body,
        })
    }

    fn mail(&self) -> OutgoingMail<'_> {
        OutgoingMail {
            message_id: self.message_id,
            date: self.date,
            sender: Party { addr_key: self.sender.0, address: &self.sender.1 },
            recipient: Party { addr_key: self.recipient.0, address: &self.recipient.1 },
            subject: &self.subject,
            body: &self.body,
        }
    }

    fn received(&self, sender_verified: bool) -> ReceivedMail {
        let mail = self.mail();
        ReceivedMail {
            message_id: mail.message_id,
            date: mail.date,
            sender: mail.sender.into(),
            sender_verified,
            recipient: mail.recipient.into(),
            subject: Zeroizing::new(self.subject.clone()),
            body: Zeroizing::new(self.body.clone()),
        }
    }
}

/// The directory as the chain gives it: a key only for a registered `addrKey` with its own full address text.
fn directory(vectors: &Value) -> impl Fn(&[u8; 32], &str) -> SenderLookup + '_ {
    move |addr_key, address| {
        Ok(items(&vectors["directory"])
            .iter()
            .find(|e| text(&e["addrKey"]) == hex::encode(addr_key) && text(&e["address"]) == address)
            .map(|e| array(&e["authPublicKey"])))
    }
}

fn me(vectors: &Value) -> ([u8; 32], String) {
    party_from(&vectors["recipient"]).unwrap()
}

fn party(owned: &([u8; 32], String)) -> Party<'_> {
    Party { addr_key: owned.0, address: &owned.1 }
}

#[test]
fn constants_match() {
    let c = &load("e2e-mail.json")["constants"];
    assert_eq!(text(&c["magic"]).as_bytes(), MAGIC);
    assert_eq!(number(&c["version"]), usize::from(VERSION));
    assert_eq!(text(&c["signatureDomain"]).as_bytes(), SIGNATURE_DOMAIN);
    assert_eq!(number(&c["messageIdLength"]), MESSAGE_ID_LENGTH);
    assert_eq!(number(&c["signatureLength"]), SIGNATURE_LENGTH);
    assert_eq!(number(&c["maxSubjectLength"]), MAX_SUBJECT_LENGTH);
    assert_eq!(number(&c["maxMailLength"]), MAX_MAIL_LENGTH);
    assert_eq!(number(&c["fixedLength"]), FIXED_LENGTH);
    assert_eq!(c["maxDate"].as_u64(), Some(MAX_DATE));
}

#[test]
fn subject_and_body_rules_match_the_vectors_for_every_code_point() {
    let ranges: Vec<(u32, u32)> = items(&load("e2e-mail.json")["constants"]["deceptiveCharacters"])
        .iter()
        .map(|r| (r[0].as_u64().unwrap().try_into().unwrap(), r[1].as_u64().unwrap().try_into().unwrap()))
        .collect();
    for c in (0..=0x10_ffff).filter_map(char::from_u32) {
        let deceptive = ranges.iter().any(|&(first, last)| (first..=last).contains(&u32::from(c)));
        assert_eq!(is_deceptive(c), deceptive, "U+{:04X}", u32::from(c));
        let subject_ok = c >= ' ' && !matches!(c, '\u{7f}' | '\u{2028}' | '\u{2029}') && !deceptive;
        let body_ok = (c >= ' ' || matches!(c, '\t' | '\n' | '\r')) && c != '\u{7f}' && !deceptive;
        let probe = format!("a{c}");
        assert_eq!(is_subject(&probe), subject_ok, "subject U+{:04X}", u32::from(c));
        assert_eq!(is_body(&probe), body_ok, "body U+{:04X}", u32::from(c));
    }
    // A byte order mark only as the first character of the body.
    assert!(is_body("\u{feff}a") && !is_subject("\u{feff}a"));
}

#[test]
fn encoding_example_is_the_first_payload() {
    let vectors = load("e2e-mail.json");
    // In layout order (serde_json does not keep the JSON order).
    let fields = [
        "magic", "version", "messageId", "date", "senderAddrKey", "senderAddress", "recipientAddrKey",
        "recipientAddress", "subject", "body",
    ];
    assert_eq!(vectors["encodingExample"].as_object().unwrap().len(), fields.len());
    let joined: String = fields.iter().map(|field| text(&vectors["encodingExample"][field])).collect();
    assert_eq!(joined, text(&vectors["valid"][0]["payload"]));
}

fn check_valid(v: &Value, vectors: &Value) {
    let name = text(&v["name"]);
    let data = MailData::from_json(&v["mail"]).unwrap();
    let mail = data.mail();
    let seed = array(&vectors["sender"]["authSecretKey"]);
    let signed = sign_mail(&seed, &mail).unwrap();
    let (payload, signature) = signed.split_at(signed.len() - SIGNATURE_LENGTH);
    assert_eq!(payload.len(), number(&v["payloadLength"]), "{name}");
    assert_eq!(Sha256::digest(payload).to_vec(), bytes(&v["payloadSha256"]), "{name}");
    if let Some(expected) = v.get("payload") {
        assert_eq!(payload, bytes(expected), "{name}");
    }
    assert_eq!(signature, bytes(&v["signature"]), "{name}: signature");
    let recipient = &vectors["recipient"];
    let (enc_public, ephemeral) = (array(&recipient["encPublicKey"]), array(&v["ephemeralSecretKey"]));
    let envelope = seal_envelope_for_vectors(&enc_public, &signed, &ephemeral, &array(&v["nonce"])).unwrap();
    assert_eq!(envelope.len(), number(&v["envelopeLength"]), "{name}");
    assert_eq!(Sha256::digest(&envelope).to_vec(), bytes(&v["envelopeSha256"]), "{name}: envelope");
    if let Some(expected) = v.get("envelope") {
        assert_eq!(envelope, bytes(expected), "{name}: envelope");
    }
    // Opened from the vector's own bytes when they are stored, so this is TypeScript's output verified in Rust.
    let stored = v.get("envelope").map_or(envelope, bytes);
    let enc_secret = array(&recipient["encSecretKey"]);
    let received = open_mail_envelope(&enc_secret, &stored, &mail.recipient, directory(vectors)).unwrap();
    assert!(received.sender_verified, "{name}");
    assert!(received == data.received(true), "{name}: fields");
}

#[test]
fn valid_vectors_are_reproduced_and_open_verified() {
    let vectors = load("e2e-mail.json");
    let valid = items(&vectors["valid"]);
    assert!(valid.len() >= 9);
    assert!(valid.iter().any(|v| number(&v["payloadLength"]) + SIGNATURE_LENGTH == MAX_MAIL_LENGTH));
    for v in valid {
        check_valid(v, &vectors);
    }
}

#[test]
fn unverified_vectors_open_with_the_claimed_sender() {
    let vectors = load("e2e-mail.json");
    let me = me(&vectors);
    let unverified = items(&vectors["unverified"]);
    assert!(unverified.len() >= 15);
    for v in unverified {
        let plaintext = bytes(&v["plaintext"]);
        assert!(is_e2e_mail(&plaintext));
        let received = open_mail(&plaintext, &party(&me), directory(&vectors)).unwrap();
        let expected = MailData::from_json(&v["mail"]).unwrap().received(false);
        assert_eq!(declared_sender(&plaintext), Ok(expected.sender.clone()), "{}", v["name"]);
        assert!(received == expected, "{}", v["name"]);
    }
}

#[test]
fn open_failures_are_one_error() {
    let vectors = load("e2e-mail.json");
    let me = me(&vectors);
    let failures = items(&vectors["openFailures"]);
    assert!(failures.len() >= 25);
    for v in failures {
        let plaintext = bytes(&v["plaintext"]);
        let result = open_mail(&plaintext, &party(&me), directory(&vectors));
        assert_eq!(result.err(), Some(MailOpenError::Invalid), "{}", v["name"]);
        assert_eq!(declared_sender(&plaintext), Err(MailOpenError::Invalid), "{}", v["name"]);
    }
}

/// `verify_strict` has no cofactor, like OpenSSL: a key with a small-order component verifies only when 8 divides k.
#[test]
fn a_mixed_order_key_gets_the_stored_verdict() {
    let vectors = load("e2e-mail.json");
    let me = me(&vectors);
    let cases = items(&vectors["mixedOrderKey"]);
    let verdicts: Vec<_> = cases.iter().map(|v| v["senderVerified"].as_bool().unwrap()).collect();
    assert_eq!(verdicts, [true, false]);
    for (v, verified) in cases.iter().zip(verdicts) {
        let received = open_mail(&bytes(&v["plaintext"]), &party(&me), directory(&vectors)).unwrap();
        assert!(received == MailData::from_json(&v["mail"]).unwrap().received(verified), "{}", v["name"]);
    }
}

#[test]
fn the_declared_sender_is_read_without_checking_the_signature() {
    let vectors = load("e2e-mail.json");
    let (data, seed, _) = sample();
    let mut plaintext = sign_mail(&seed, &data.mail()).unwrap().to_vec();
    let expected = Address::from(data.mail().sender);
    assert_eq!(declared_sender(&plaintext), Ok(expected.clone()));
    // Same answer with a broken signature: nothing but the format is checked.
    *plaintext.last_mut().unwrap() ^= 1;
    assert_eq!(declared_sender(&plaintext), Ok(expected));
    assert!(!open_mail(&plaintext, &data.mail().recipient, directory(&vectors)).unwrap().sender_verified);
}

#[test]
fn a_resolver_that_cannot_answer_is_retried_later_not_unverified() {
    let (data, seed, _) = sample();
    let plaintext = sign_mail(&seed, &data.mail()).unwrap();
    let me = data.mail().recipient;
    let unavailable = |_: &[u8; 32], _: &str| Err(SenderUnavailable);
    assert_eq!(open_mail(&plaintext, &me, unavailable).err(), Some(MailOpenError::SenderUnavailable));
    // Not asked when the mail was signed for someone else: that mail is unverified whatever the registry says.
    let someone_else = Party { addr_key: me.addr_key, address: "pepe@nightmail.local" };
    assert!(!open_mail(&plaintext, &someone_else, unavailable).unwrap().sender_verified);
    // The format is checked first: an invalid mail is invalid, not "try again".
    assert_eq!(open_mail(&plaintext[1..], &me, unavailable).err(), Some(MailOpenError::Invalid));
}

/// Rebuilt with the internal writer (the public one refuses it), signed like any other mail.
#[test]
fn oversized_mail_is_rejected() {
    let vectors = load("e2e-mail.json");
    let v = &vectors["openFailureOversized"];
    let data = MailData::from_json(&v["mail"]).unwrap();
    let mail = data.mail();
    assert_eq!(check(&mail).err(), Some(MailBuildError::Field(MailField::Body)));
    let lengths = Lengths {
        sender: u8::try_from(mail.sender.address.len()).unwrap(),
        recipient: u8::try_from(mail.recipient.address.len()).unwrap(),
        subject: u16::try_from(mail.subject.len()).unwrap(),
        body: u32::try_from(mail.body.len()).unwrap(),
        total: 0,
    };
    let mut plaintext = SIGNATURE_DOMAIN.to_vec();
    write_payload(&mut plaintext, &mail, &lengths);
    let signature = SigningKey::from_bytes(&array(&vectors["sender"]["authSecretKey"])).sign(&plaintext);
    plaintext.drain(..SIGNATURE_DOMAIN.len());
    plaintext.extend_from_slice(&signature.to_bytes());
    assert_eq!(plaintext.len(), number(&v["plaintextLength"]));
    assert_eq!(Sha256::digest(&plaintext).to_vec(), bytes(&v["plaintextSha256"]));
    let me = me(&vectors);
    assert_eq!(open_mail(&plaintext, &party(&me), directory(&vectors)).err(), Some(MailOpenError::Invalid));
}

#[test]
fn encode_failures_are_refused_by_field() {
    let vectors = load("e2e-mail.json");
    let failures = items(&vectors["encodeFailures"]);
    assert!(failures.len() >= 25);
    let seed = array(&vectors["sender"]["authSecretKey"]);
    for v in failures {
        let name = &v["name"];
        let field = text(&v["field"]);
        // Either the Rust types cannot even hold it, or building fails on that same field.
        if let Some(data) = MailData::from_json(&v["mail"]) {
            let error = sign_mail(&seed, &data.mail()).err();
            assert_eq!(error.map(|e| e.to_string()), Some(format!("invalid mail field: {field}")), "{name}");
        }
        let mut repaired = v["mail"].clone();
        let source = &vectors["valid"][0]["mail"];
        repaired[field] = source[field].clone();
        if field == "body" {
            repaired.as_object_mut().unwrap().retain(|key, _| key != "bodyPattern" && key != "bodyLength");
        }
        let data = MailData::from_json(&repaired).unwrap();
        assert!(sign_mail(&seed, &data.mail()).is_ok(), "{name}: the rejection is not due to `{field}`");
    }
}

// --- Beyond the vectors ---

fn sample() -> (MailData, [u8; 32], [u8; 32]) {
    let vectors = load("e2e-mail.json");
    let data = MailData::from_json(&vectors["valid"][0]["mail"]).unwrap();
    (data, array(&vectors["sender"]["authSecretKey"]), array(&vectors["recipient"]["encSecretKey"]))
}

#[test]
fn seal_mail_uses_fresh_randomness_and_opens_verified() {
    let vectors = load("e2e-mail.json");
    let (data, seed, enc_secret) = sample();
    let enc_public = array(&vectors["recipient"]["encPublicKey"]);
    let seal = || seal_mail(&seed, &enc_public, &data.mail()).unwrap();
    let (a, b) = (seal(), seal());
    assert_ne!(a[2..46], b[2..46], "ephemeral key and nonce");
    assert_eq!(a[..2], [1, 1]);
    for envelope in [a, b] {
        let received = open_mail_envelope(&enc_secret, &envelope, &data.mail().recipient, directory(&vectors)).unwrap();
        assert!(received == data.received(true));
    }
}

#[test]
fn seal_mail_refuses_unusable_recipient_keys() {
    let (data, seed, _) = sample();
    for k in items(&load("mailbox.json")["sealFailures"]["lowOrderRecipientPublicKeys"]) {
        assert_eq!(seal_mail(&seed, &array(k), &data.mail()), Err(MailBuildError::RecipientKey), "{k}");
    }
}

#[test]
fn opening_with_another_key_or_a_mime_message_is_the_same_error() {
    let vectors = load("e2e-mail.json");
    let (data, seed, enc_secret) = sample();
    let enc_public = array(&vectors["recipient"]["encPublicKey"]);
    let envelope = seal_mail(&seed, &enc_public, &data.mail()).unwrap();
    let me = data.mail().recipient;
    assert_eq!(open_mail_envelope(&[9; 32], &envelope, &me, directory(&vectors)).err(), Some(MailOpenError::Invalid));
    assert_eq!(open_mail_envelope(&enc_secret, &envelope[1..], &me, directory(&vectors)).err(), Some(MailOpenError::Invalid));
    let mime = seal_envelope(&enc_public, b"From: a@b\r\n\r\nhola").unwrap();
    assert!(!is_e2e_mail(b"From: a@b\r\n\r\nhola"));
    assert_eq!(open_mail_envelope(&enc_secret, &mime, &me, directory(&vectors)).err(), Some(MailOpenError::Invalid));
}

#[test]
fn the_resolver_gets_the_claimed_sender_and_is_skipped_for_someone_else() {
    let vectors = load("e2e-mail.json");
    let (data, seed, _) = sample();
    let plaintext = sign_mail(&seed, &data.mail()).unwrap();
    let calls = Cell::new(0);
    let resolve = |addr_key: &[u8; 32], address: &str| {
        calls.set(calls.get() + 1);
        assert_eq!((*addr_key, address), (data.sender.0, data.sender.1.as_str()));
        directory(&vectors)(addr_key, address)
    };
    assert!(open_mail(&plaintext, &data.mail().recipient, resolve).unwrap().sender_verified);
    let someone_else = Party { addr_key: data.recipient.0, address: "pepe@nightmail.local" };
    let received = open_mail(&plaintext, &someone_else, resolve).unwrap();
    assert!(!received.sender_verified);
    assert_eq!(received.sender.address, data.sender.1);
    assert_eq!(calls.get(), 1);
}

#[test]
fn a_resolver_returning_an_unusable_key_gives_not_verified() {
    let (data, seed, _) = sample();
    let plaintext = sign_mail(&seed, &data.mail()).unwrap();
    for key in [[0; 32], [0xff; 32]] {
        assert!(!open_mail(&plaintext, &data.mail().recipient, |_, _| Ok(Some(key))).unwrap().sender_verified);
    }
}

#[test]
fn the_size_limit_counts_the_whole_mail() {
    let (data, seed, _) = sample();
    let mut mail = data.mail();
    mail.subject = "";
    let overhead = FIXED_LENGTH + mail.sender.address.len() + mail.recipient.address.len();
    let body = "a".repeat(MAX_MAIL_LENGTH - overhead);
    mail.body = &body;
    assert_eq!(sign_mail(&seed, &mail).unwrap().len(), MAX_MAIL_LENGTH);
    let longer = format!("{body}a");
    mail.body = &longer;
    assert_eq!(sign_mail(&seed, &mail).err(), Some(MailBuildError::Field(MailField::Body)));
}

#[test]
fn errors_and_debug_reveal_no_content() {
    assert_eq!(MailOpenError::Invalid.to_string(), "invalid mail");
    assert_eq!(MailOpenError::SenderUnavailable.to_string(), "sender check unavailable");
    assert_eq!(MailBuildError::Field(MailField::Subject).to_string(), "invalid mail field: subject");
    assert_eq!(MailBuildError::RecipientKey.to_string(), "unusable recipient key");
    let (data, _, _) = sample();
    let debug = format!("{:?}", data.received(true));
    assert!(!debug.contains(&data.subject) && !debug.contains("Hola"), "{debug}");
}
